package dashboard.enterprise.agent.llm.provider;
import dashboard.enterprise.agent.llm.model.*;import dashboard.enterprise.agent.model.AgentContext;import java.util.*;
public final class FallbackLlmProvider implements LlmProvider {private final String id;private final List<LlmProvider> chain;public FallbackLlmProvider(String id,List<LlmProvider> chain){this.id=id;this.chain=List.copyOf(chain);if(chain.isEmpty())throw new IllegalArgumentException("Fallback chain is required.");}
 public String providerId(){return id;}public LlmProviderType providerType(){return chain.get(0).providerType();}public int priority(){return chain.stream().mapToInt(LlmProvider::priority).max().orElse(0)+1;}public boolean available(){return chain.stream().anyMatch(LlmProvider::available);}public Set<String> capabilities(){Set<String>s=new LinkedHashSet<>();chain.forEach(p->s.addAll(p.capabilities()));return Set.copyOf(s);}public LlmModelConfiguration model(){return chain.get(0).model();}
 public LlmResponse generate(AgentContext context,LlmRequest request)throws Exception{Exception last=null;for(LlmProvider p:chain){if(!p.available()||!p.supports(request.capabilityId()))continue;try{return p.generate(context,request);}catch(Exception ex){last=ex;}}if(last!=null)throw last;throw new IllegalStateException("No available LLM provider in fallback chain.");}}
